import React from "react";
import { useNavigate } from "react-router-dom";

const RoleSelection = () => {
  const navigate = useNavigate();

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/");
  };

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gradient-to-r from-green-400 to-blue-500">
      <h1 className="text-3xl font-bold text-white mb-6">Select Your Role</h1>
      <div className="flex flex-col gap-4">
        <button className="bg-white text-gray-800 p-3 rounded hover:bg-gray-200 transition">
          Student
        </button>
        <button className="bg-white text-gray-800 p-3 rounded hover:bg-gray-200 transition">
          Professional
        </button>
        <button className="bg-white text-gray-800 p-3 rounded hover:bg-gray-200 transition">
          Homemaker
        </button>
        <button className="bg-white text-gray-800 p-3 rounded hover:bg-gray-200 transition">
          Custom Role
        </button>
        <button
          className="mt-4 bg-red-500 text-white p-2 rounded hover:bg-red-600 transition"
          onClick={logout}
        >
          Logout
        </button>
      </div>
    </div>
  );
};

export default RoleSelection;
